Lemma rsmall_cnt_read : forall m sc i, mem_inv usegs m -> 0 <= sc < 9 -> 0 <= i < 3 ->
  ov_read_bytes usegs m (wa (RSMALL_CNT + 3 * sc + i)) 1 = Some [b8 (small_cnt sc i)].
